/** Full phrase bank: reviewed core strings plus workspace-wide additions. */
export const PHRASES: Record<string, Entry> = { ...PHRASES_BASE, ...EXTRA_PHRASES };

/** The language the app is currently rendering in, for model-level labels. */
let activeLang: Lang = "en";
export function setActiveLang(lang: Lang) {
  activeLang = lang;
}
export function getActiveLang(): Lang {
  return activeLang;
}

/** Translate a visible English phrase into the selected language. */
export function translate(lang: Lang, text: string, vars?: Record<string, string | number>): string {
  const entry = lang === "en" ? undefined : PHRASES[text];
  let out = entry ? entry[lang] ?? entry.en : text;
  if (vars) {
    for (const [key, value] of Object.entries(vars)) out = out.split(`{${key}}`).join(String(value));
  }
  return out;
}
